use serde_json::json;
use std::panic::{AssertUnwindSafe, catch_unwind};

#[test]
fn huge_path_fill_overflows() {
    let mut s = Session::new();
    s.execute("file.new", json!({"width": 48, "height": 32})).unwrap();
    s.execute("layer.new.layer", json!({})).unwrap();
    let path = json!({"name": "P", "path": {"subpaths": [
        {"closed": true, "knots": [[0.0, 0.0], [3.0e9, 0.0], [3.0e9, 1.0e9]]}
    ]}});
    let _ = catch_unwind(AssertUnwindSafe(|| {
        let _ = s.execute("path.set", path);
        let _ = s.execute("path.fill", json!({"name": "P", "color": "#ff0000"}));
    }));
}
```

